// Material properties per IS 456:2000 — port of material_properties(fck, fy).
const fck = Number(inputs["fck"]) || 0;   // MPa, characteristic concrete strength
const fy  = Number(inputs["fy"])  || 0;   // MPa, characteristic steel strength

const Es  = 200000.0;                     // MPa
const Ec  = 5000.0 * Math.sqrt(fck);      // MPa  (IS 456 Cl 6.2.1)
const fcd = 0.45 * fck;                   // MPa  (ULS concrete design strength)
const fyd = 0.87 * fy;                    // MPa  (ULS steel design strength)

return { "Es": Es, "Ec": Ec, "fcd": fcd, "fyd": fyd };

// Reinforcement layout for a circular section.
// Port of CircularSection._place_steel(): single bars, bundles (2) and
// triplets (3), one or two concentric layers, plus optional extra layers.
// Outputs the total steel area and a JSON description of the bar layers that
// the ULS / SLS nodes consume (they rebuild the same bar coordinates).
const D      = Number(inputs["D"]) || 0;                        // mm
const cover  = Number(inputs["cover"]) || 0;                    // mm
const n_bars = Math.round(Number(inputs["n_bars"]) || 0);
const dia    = Number(inputs["dia"]) || 0;                      // mm
const group  = String(inputs["group_type"] || "single").trim().toLowerCase();
const twoLay = Boolean(inputs["two_layer"]);
const extra  = String(inputs["extra_layers"] || "").trim();      // "n:dia:r[:group];..."

if (D <= 0) throw new Error("D must be greater than 0");
const R = D / 2;
const r_out = R - cover - dia / 2;
if (r_out <= 0) throw new Error("cover + dia/2 exceeds the section radius");

const PER = { single: 1, bundle: 2, triplet: 3 };
function perGroup(g) {
  if (PER[g] === undefined) throw new Error('group_type must be single, bundle or triplet (got "' + g + '")');
  return PER[g];
}

// ── layer list (menu options 1, 2 and 3 of the original script) ──
const layers = [];
const bpg = perGroup(group);
if (twoLay) {
  if (n_bars % (bpg * 2) !== 0) throw new Error("two layers need a bar count divisible by " + (bpg * 2));
  const n1 = Math.floor(n_bars / 2);
  layers.push({ n: n1, dia: dia, r: r_out, group: group });
  layers.push({ n: n_bars - n1, dia: dia, r: r_out - Math.max(dia, 25.0), group: group });
} else {
  if (n_bars % bpg !== 0) throw new Error("bar count " + n_bars + " is not divisible by " + bpg + ' for "' + group + '"');
  layers.push({ n: n_bars, dia: dia, r: r_out, group: group });
}
if (extra !== "") {
  extra.split(";").forEach(function (chunk) {
    const s = chunk.trim();
    if (s === "") return;
    const p = s.split(":");
    if (p.length < 3) throw new Error('extra_layers entry "' + s + '" must be n:dia:radius[:group]');
    layers.push({
      n: Math.round(Number(p[0])), dia: Number(p[1]), r: Number(p[2]),
      group: String(p[3] || "single").trim().toLowerCase(),
    });
  });
}

// ── place the bars ──
const bars = [];
layers.forEach(function (L) {
  const per = perGroup(L.group);
  if (L.n % per !== 0) throw new Error("layer with " + L.n + ' bars is not divisible by ' + per + ' ("' + L.group + '")');
  if (L.r <= 0) throw new Error("layer radius must be greater than 0");
  const nGroups = L.n / per;
  const aBar = Math.PI * L.dia * L.dia / 4;
  const dth = per > 1 ? L.dia / L.r : 0;          // arc spacing ~= bar diameter
  for (let i = 0; i < nGroups; i++) {
    const base = 2 * Math.PI * i / nGroups;
    const angles = per === 1 ? [base]
      : per === 2 ? [base - dth / 2, base + dth / 2]
      : [base - dth, base, base + dth];
    for (let k = 0; k < angles.length; k++) {
      bars.push([L.r * Math.cos(angles[k]), L.r * Math.sin(angles[k]), aBar]);
    }
  }
});

let Asc = 0, r_max = 0;
for (let i = 0; i < bars.length; i++) {
  Asc += bars[i][2];
  r_max = Math.max(r_max, Math.sqrt(bars[i][0] * bars[i][0] + bars[i][1] * bars[i][1]));
}
const Ac = Math.PI * R * R;
const p_steel = Ac > 0 ? 100 * Asc / Ac : 0;
const layout = layers.map(function (L) {
  return L.n + " x " + L.dia + "mm @ r=" + L.r.toFixed(1) + " (" + L.group + ")";
}).join("  +  ");

return {
  "Asc": Asc,
  "Ac": Ac,
  "p_steel": p_steel,
  "r_bar": r_max,
  "n_placed": bars.length,
  "layers_json": JSON.stringify(layers),
  "layout": layout
};

// ULS biaxial bending check for a circular RC section — IS 456:2000 Cl 39.6.
// Port of CircularSection.check_uls() + uniaxial_capacity_uls().
// Fibre model with strain compatibility: parabolic-rectangular concrete
// (fcd = 0.45 fck, eps_cu = 0.0035) and bilinear steel (fyd = 0.87 fy).
// The neutral-axis depth is scanned over logspace(-2, 3, 300) * R, the N-M
// points are sorted by N and the moment at the demanded axial load is read off
// by linear interpolation (largest value where the curve is multi-valued).
// Loads enter in kN / kNm, capacities leave in kN / kNm.
const D      = Number(inputs["D"]) || 0;                    // mm
const dx     = Number(inputs["dx"]) || 5;                  // mm, fibre grid (original script used 5)
const fck    = Number(inputs["fck"]) || 0;                  // MPa
const fy     = Number(inputs["fy"]) || 0;                   // MPa
const Asc    = Number(inputs["Asc"]) || 0;                  // mm2
const Pu     = (Number(inputs["Pu"])  || 0) * 1000;         // kN  -> N
const Mux    = (Number(inputs["Mux"]) || 0) * 1e6;          // kNm -> Nmm
const Muy    = (Number(inputs["Muy"]) || 0) * 1e6;          // kNm -> Nmm
const layers = JSON.parse(String(inputs["layers_json"] || "[]"));

// ── shared section builder (fibre grid + bar coordinates) ──
function placeBars(layers) {
  const PER = { single: 1, bundle: 2, triplet: 3 };
  const bx = [], by = [], ba = [];
  for (let i = 0; i < layers.length; i++) {
    const L = layers[i];
    const per = PER[L.group] === undefined ? 1 : PER[L.group];
    if (L.n % per !== 0) throw new Error("layer with " + L.n + " bars is not divisible by " + per);
    const nGroups = L.n / per;
    const aBar = Math.PI * L.dia * L.dia / 4;
    const dth = per > 1 ? L.dia / L.r : 0;
    for (let g = 0; g < nGroups; g++) {
      const base = 2 * Math.PI * g / nGroups;
      const angles = per === 1 ? [base]
        : per === 2 ? [base - dth / 2, base + dth / 2]
        : [base - dth, base, base + dth];
      for (let k = 0; k < angles.length; k++) {
        bx.push(L.r * Math.cos(angles[k]));
        by.push(L.r * Math.sin(angles[k]));
        ba.push(aBar);
      }
    }
  }
  return { bx: bx, by: by, ba: ba };
}

function buildFibres(R, dx) {
  // Matches np.arange(-R, R, dx): points -R + i*dx while the value is < R.
  const fx = [], fy = [], fa = [];
  const nStep = Math.ceil(2 * R / dx);
  for (let i = 0; i < nStep; i++) {
    const x = -R + i * dx;
    if (x >= R) break;
    for (let j = 0; j < nStep; j++) {
      const y = -R + j * dx;
      if (y >= R) break;
      if (x * x + y * y <= R * R) { fx.push(x + dx / 2); fy.push(y + dx / 2); fa.push(dx * dx); }
    }
  }
  return { fx: fx, fy: fy, fa: fa };
}

if (D <= 0) throw new Error("D must be greater than 0");
if (dx <= 0) throw new Error("fibre grid dx must be greater than 0");
const R = D / 2;
const fib = buildFibres(R, dx);
const bar = placeBars(layers);
const nf = fib.fa.length, nb = bar.ba.length;

const EPS_CU = 0.0035;
const Es = 200000.0;
const fcd = 0.45 * fck;
const fyd = 0.87 * fy;
const NPTS = 300;

// Both uniaxial axes are accumulated in one pass per neutral-axis depth
// (the strain field for x-axis bending varies with y, for y-axis with x).
const resX = [], resY = [];
for (let i = 0; i < NPTS; i++) {
  const c = R * Math.pow(10, -2 + 5 * i / (NPTS - 1));
  const kappa = EPS_CU / c;
  const eps0 = -kappa * (R - c);
  let Nx = 0, Mx = 0, Ny = 0, My = 0;

  for (let k = 0; k < nf; k++) {
    const a = fib.fa[k];
    const ex = eps0 + kappa * fib.fy[k];
    let sc = 0;
    if (ex > 0) {
      if (ex <= 0.002) { const q = ex / 0.002; sc = fcd * (2 * q - q * q); }
      else if (ex <= 0.0035) { sc = fcd; }
    }
    Nx += sc * a; Mx += sc * a * fib.fy[k];

    const ey = eps0 + kappa * fib.fx[k];
    let sc2 = 0;
    if (ey > 0) {
      if (ey <= 0.002) { const q = ey / 0.002; sc2 = fcd * (2 * q - q * q); }
      else if (ey <= 0.0035) { sc2 = fcd; }
    }
    Ny += sc2 * a; My += sc2 * a * fib.fx[k];
  }

  for (let k = 0; k < nb; k++) {
    const a = bar.ba[k];
    let s1 = Es * (eps0 + kappa * bar.by[k]);
    if (s1 > fyd) s1 = fyd; else if (s1 < -fyd) s1 = -fyd;
    Nx += s1 * a; Mx += s1 * a * bar.by[k];

    let s2 = Es * (eps0 + kappa * bar.bx[k]);
    if (s2 > fyd) s2 = fyd; else if (s2 < -fyd) s2 = -fyd;
    Ny += s2 * a; My += s2 * a * bar.bx[k];
  }

  resX.push([Nx, Mx]);
  resY.push([Ny, My]);
}

function capacityAt(res, P) {
  const s = res.slice().sort(function (a, b) { return a[0] - b[0]; });
  let best = null;
  for (let i = 0; i < s.length - 1; i++) {
    const n0 = s[i][0], m0 = s[i][1], n1 = s[i + 1][0], m1 = s[i + 1][1];
    if ((n0 - P) * (n1 - P) <= 0 && Math.abs(n1 - n0) > 1e-12) {
      const t = (P - n0) / (n1 - n0);
      const m = m0 + t * (m1 - m0);
      if (best === null || m > best) best = m;
    }
  }
  return best === null ? 0 : best;
}

const Mux1 = capacityAt(resX, Pu);      // Nmm
const Muy1 = capacityAt(resY, Pu);      // Nmm

// Squash load per Cl 39.6.1.2 (gross concrete area + 0.75 fy Asc)
const Puz = 0.45 * fck * (Math.PI * R * R) + 0.75 * fy * Asc;   // N

let alpha_n = Puz > 0 ? 0.667 + 1.667 * (Pu / Puz) : 1.0;
alpha_n = Math.max(1.0, Math.min(2.0, alpha_n));

const ratio = (Mux1 > 0 && Muy1 > 0)
  ? Math.pow(Math.abs(Mux) / Mux1, alpha_n) + Math.pow(Math.abs(Muy) / Muy1, alpha_n)
  : 1e9;
const safe = ratio <= 1.0;
const Status = (safe ? "SAFE " : "UNSAFE ") + ratio.toFixed(3)
  + (Mux1 > 0 && Muy1 > 0 ? "" : " (no N-M bracket)");

return {
  "Puz": Puz / 1000,
  "Mux1": Mux1 / 1e6,
  "Muy1": Muy1 / 1e6,
  "alpha_n": alpha_n,
  "ratio": ratio,
  "Status": Status
};

// SLS check for a circular RC section — cracked transformed-section analysis
// plus the IS 456:2000 Cl 4.3.2 crack-width expression.
// Port of CircularSection.sls_uniaxial() and check_sls().
// Concrete is linear elastic and carries compression only; steel is linear
// elastic (Es = 200000 MPa). The neutral axis is found as the fixed point of
// c = R + eps0/kappa by bracketed bisection over [0.01 R, 10 D] — the
// dependency-free stand-in for scipy's brentq (same bracket contract, and the
// same 10 D fallback when no bracket exists).
// Loads enter in kN / kNm, stresses leave in MPa, crack width in mm.
const D      = Number(inputs["D"]) || 0;                     // mm
const cover  = Number(inputs["cover"]) || 0;                 // mm
const dx     = Number(inputs["dx"]) || 5;                   // mm, fibre grid (original script used 5)
const fck    = Number(inputs["fck"]) || 0;                   // MPa
const fy     = Number(inputs["fy"]) || 0;                    // MPa
const Ec     = Number(inputs["Ec"]) || 0;                    // MPa
const Es     = Number(inputs["Es"]) || 200000;               // MPa
const P      = (Number(inputs["P"])  || 0) * 1000;           // kN  -> N
const Mx_in  = (Number(inputs["Mx"]) || 0) * 1e6;            // kNm -> Nmm
const My_in  = (Number(inputs["My"]) || 0) * 1e6;            // kNm -> Nmm
const layers = JSON.parse(String(inputs["layers_json"] || "[]"));

// ── shared section builder (fibre grid + bar coordinates) ──
function placeBars(layers) {
  const PER = { single: 1, bundle: 2, triplet: 3 };
  const bx = [], by = [], ba = [];
  for (let i = 0; i < layers.length; i++) {
    const L = layers[i];
    const per = PER[L.group] === undefined ? 1 : PER[L.group];
    if (L.n % per !== 0) throw new Error("layer with " + L.n + " bars is not divisible by " + per);
    const nGroups = L.n / per;
    const aBar = Math.PI * L.dia * L.dia / 4;
    const dth = per > 1 ? L.dia / L.r : 0;
    for (let g = 0; g < nGroups; g++) {
      const base = 2 * Math.PI * g / nGroups;
      const angles = per === 1 ? [base]
        : per === 2 ? [base - dth / 2, base + dth / 2]
        : [base - dth, base, base + dth];
      for (let k = 0; k < angles.length; k++) {
        bx.push(L.r * Math.cos(angles[k]));
        by.push(L.r * Math.sin(angles[k]));
        ba.push(aBar);
      }
    }
  }
  return { bx: bx, by: by, ba: ba };
}

function buildFibres(R, dx) {
  // Matches np.arange(-R, R, dx): points -R + i*dx while the value is < R.
  const fx = [], fy = [], fa = [];
  const nStep = Math.ceil(2 * R / dx);
  for (let i = 0; i < nStep; i++) {
    const x = -R + i * dx;
    if (x >= R) break;
    for (let j = 0; j < nStep; j++) {
      const y = -R + j * dx;
      if (y >= R) break;
      if (x * x + y * y <= R * R) { fx.push(x + dx / 2); fy.push(y + dx / 2); fa.push(dx * dx); }
    }
  }
  return { fx: fx, fy: fy, fa: fa };
}

if (D <= 0) throw new Error("D must be greater than 0");
if (Ec <= 0 || Es <= 0) throw new Error("Ec and Es must be greater than 0");
const R = D / 2;
const fib = buildFibres(R, dx);
const bar = placeBars(layers);
const nf = fib.fa.length, nb = bar.ba.length;
const M = Math.sqrt(Mx_in * Mx_in + My_in * My_in);          // resultant, Nmm

let eps0 = 0, kappa = 0, sigma_c = 0, sigma_s = 0, c = 0, crack = 0;

if (M < 1e-6) {
  // Uncracked / axial only — the original script's early return.
  sigma_c = P / (Math.PI * R * R);
  sigma_s = Es * (sigma_c / Ec);
  c = 0;
} else {
  // Transformed section properties for a trial neutral axis at y = R - cg.
  function stateAt(cg) {
    const yNA = R - cg;
    let Ac = 0, Sc = 0, Ic = 0;
    for (let k = 0; k < nf; k++) {
      const y = fib.fy[k];
      if (y >= yNA) { const a = fib.fa[k]; Ac += a; Sc += y * a; Ic += y * y * a; }
    }
    let As = 0, Ss = 0, Is = 0;
    for (let k = 0; k < nb; k++) { const y = bar.by[k], a = bar.ba[k]; As += a; Ss += y * a; Is += y * y * a; }
    const A = Ec * Ac + Es * As;
    const B = Ec * Sc + Es * Ss;
    const C = Ec * Ic + Es * Is;
    return { A: A, B: B, C: C, det: A * C - B * B };
  }

  function solveAt(st) {
    const e0 = (P * st.C - M * st.B) / st.det;
    const kap = (st.A * M - st.B * P) / st.det;
    return { eps0: e0, kappa: kap };
  }

  function residual(cg) {
    const st = stateAt(cg);
    if (Math.abs(st.det) < 1e-12) return 1e9;
    const s = solveAt(st);
    const yNAa = Math.abs(s.kappa) > 1e-12 ? -s.eps0 / s.kappa : (s.eps0 >= 0 ? -R : R);
    return (R - yNAa) - cg;
  }

  // Bracketed bisection (brentq stand-in).
  let lo = 0.01 * R, hi = 10 * D;
  let flo = residual(lo), fhi = residual(hi);
  let solved = isFinite(flo) && isFinite(fhi) && (flo === 0 || fhi === 0 || flo * fhi < 0);
  if (!solved) {
    let px = lo, pf = flo;
    for (let i = 1; i <= 200; i++) {
      const x = lo + (hi - lo) * i / 200;
      const fx = residual(x);
      if (isFinite(fx) && isFinite(pf) && pf * fx <= 0) { hi = x; fhi = fx; lo = px; flo = pf; solved = true; break; }
      px = x; pf = fx;
    }
  }
  if (solved) {
    for (let it = 0; it < 200; it++) {
      const mid = 0.5 * (lo + hi);
      const fm = residual(mid);
      if (!isFinite(fm)) break;
      if (fm === 0 || (hi - lo) < 1e-3) { lo = mid; break; }
      if (flo * fm < 0) { hi = mid; fhi = fm; } else { lo = mid; flo = fm; }
    }
    c = 0.5 * (lo + hi);
  } else {
    c = 10 * D;                     // same fallback as the original script
  }

  const st = stateAt(c);
  if (Math.abs(st.det) < 1e-12) throw new Error("degenerate transformed section (det ~ 0)");
  const sol = solveAt(st);
  eps0 = sol.eps0;
  kappa = sol.kappa;

  const strain_top = eps0 + kappa * R;
  sigma_c = Ec * Math.max(strain_top, 0);

  let minStress = 0;
  let min_y = nb > 0 ? bar.by[0] : 0;
  for (let k = 0; k < nb; k++) {
    if (bar.by[k] < min_y) min_y = bar.by[k];
    const s = Es * (eps0 + kappa * bar.by[k]);
    if (s < minStress) minStress = s;
  }
  sigma_s = Math.abs(minStress);

  // ── crack width, IS 456 Cl 4.3.2 (a_cr assumes a 12 mm bar, as in the
  //    original script: a_cr = cover + 12) ──
  if (nb > 0) {
    const a_cr = cover + 12.0;
    const c_min = cover;
    const h = D;
    const x = c;
    const d = R - min_y;                 // top fibre to the lowest bar
    const es = Math.abs(eps0 + kappa * min_y);
    const b = D;
    let As_t = 0;
    for (let k = 0; k < nb; k++) { if (bar.by[k] <= 0) As_t += bar.ba[k]; }
    let eps_m = es;
    const dhx = h - x, ddx = d - x;
    if (As_t > 0 && Math.abs(ddx) > 1e-9 && dhx !== 0) {
      eps_m = es - (b * dhx * dhx) / (3 * Es * As_t * ddx);
    }
    if (eps_m < 0) eps_m = 0;
    const denom = dhx !== 0 ? 1 + 2 * (a_cr - c_min) / dhx : 0;
    crack = denom > 0 ? 3 * a_cr * eps_m / denom : 0;
  }
}

const sc_lim = 0.45 * fck;
const ss_lim = 0.87 * fy;
const cr_lim = 0.3;
const fails = [];
if (sigma_c > sc_lim) fails.push("concrete " + sigma_c.toFixed(2) + ">" + sc_lim.toFixed(2));
if (sigma_s > ss_lim) fails.push("steel " + sigma_s.toFixed(2) + ">" + ss_lim.toFixed(2));
if (crack > cr_lim) fails.push("crack " + crack.toFixed(3) + ">" + cr_lim.toFixed(3));
const Status = fails.length === 0 ? "OK " + sigma_c.toFixed(2) + " MPa / " + crack.toFixed(3) + " mm"
  : "NOT OK (" + fails.join(", ") + ")";

return {
  "eps0": eps0,
  "kappa": kappa,
  "c_NA": c,
  "sigma_c": sigma_c,
  "sigma_s": sigma_s,
  "crack": crack,
  "Status": Status
};
